  1	package queue;
  2	
  3	import java.util.AbstractQueue;
  4	import java.util.Arrays;
  5	import java.util.ConcurrentModificationException;
  6	import java.util.Iterator;
  7	import java.util.NoSuchElementException;
  8	import java.util.Objects;
  9	
 10	public final class CircularQueue<T> extends AbstractQueue<T> implements BoundedQueue<T> {
 11	
 12	    private static final String EMPTY_QUEUE_MESSAGE = "Queue is empty.";
 13	    private static final String FULL_QUEUE_MESSAGE = "Queue is full.";
 14	
 15	    private final Object[] elements;
 16	    private int head;
 17	    private int tail;
 18	    private int size;
 19	    private int modificationCount;
 20	
 21	    public CircularQueue(int capacity) {
 22	        if (capacity <= 0) {
 23	            throw new IllegalArgumentException("Capacity must be positive.");
 24	        }
 25	
 26	        elements = new Object[capacity];
 27	        resetState();
 28	    }
 29	
 30	    public void enqueue(T value) {
 31	        if (!offer(value)) {
 32	            throw new IllegalStateException(FULL_QUEUE_MESSAGE);
 33	        }
 34	    }
 35	
 36	    public T dequeue() {
 37	        requireNotEmpty();
 38	        return poll();
 39	    }
 40	
 41	    public T peekFront() {
 42	        requireNotEmpty();
 43	        return elementAt(head);
 44	    }
 45	
 46	    public T peekRear() {
 47	        requireNotEmpty();
 48	        return elementAt(indexFromHead(size - 1));
 49	    }
 50	
 51	    public T getFront() {
 52	        return peekFront();
 53	    }
 54	
 55	    public T getRear() {
 56	        return peekRear();
 57	    }
 58	
 59	    public boolean isEmpty() {
 60	        return size == 0;
 61	    }
 62	
 63	    @Override
 64	    public boolean offer(T value) {
 65	        Objects.requireNonNull(value, "Queue elements must be non-null.");
 66	
 67	        if (isFull()) {
 68	            return false;
 69	        }
 70	
 71	        insertAtTail(value);
 72	        recordMutation();
 73	        return true;
 74	    }
 75	
 76	    @Override
 77	    public T poll() {
 78	        if (isEmpty()) {
 79	            return null;
 80	        }
 81	
 82	        T removedValue = removeHead();
 83	        recordMutation();
 84	        return removedValue;
 85	    }
 86	
 87	    @Override
 88	    public T peek() {
 89	        if (isEmpty()) {
 90	            return null;
 91	        }
 92	        return elementAt(head);
 93	    }
 94	
 95	    @Override
 96	    public int size() {
 97	        return size;
 98	    }
 99	
100	    public int capacity() {
101	        return elements.length;
102	    }
103	
104	    @Override
105	    public void clear() {
106	        Arrays.fill(elements, null);
107	        resetState();
108	        recordMutation();
109	    }
110	
111	    @Override
112	    public Iterator<T> iterator() {
113	        return new QueueIterator();
114	    }
115	
116	    @Override
117	    public String toString() {
118	        StringBuilder builder = new StringBuilder();
119	        builder.append('[');
120	
121	        for (int offset = 0; offset < size; offset++) {
122	            if (offset > 0) {
123	                builder.append(", ");
124	            }
125	
126	            builder.append(elementAt(indexFromHead(offset)));
127	        }
128	
129	        builder.append(']');
130	        return builder.toString();
131	    }
132	
133	    private int advance(int index) {
134	        return (index + 1) % elements.length;
135	    }
136	
137	    private int indexFromHead(int offset) {
138	        return (head + offset) % elements.length;
139	    }
140	
141	    private void resetState() {
142	        head = 0;
143	        tail = 0;
144	        size = 0;
145	    }
146	
147	    private void recordMutation() {
148	        modificationCount++;
149	    }
150	
151	    private void requireNotEmpty() {
152	        if (isEmpty()) {
153	            throw new IllegalStateException(EMPTY_QUEUE_MESSAGE);
154	        }
155	    }
156	
157	    private void insertAtTail(T value) {
158	        elements[tail] = value;
159	        tail = advance(tail);
160	        size++;
161	    }
162	
163	    private T removeHead() {
164	        T removedValue = elementAt(head);
165	        elements[head] = null;
166	        head = advance(head);
167	        size--;
168	        return removedValue;
169	    }
170	
171	    @SuppressWarnings("unchecked")
172	    private T elementAt(int index) {
173	        return (T) elements[index];
174	    }
175	
176	    private final class QueueIterator implements Iterator<T> {
177	        private final int expectedModificationCount = modificationCount;
178	        private int offset;
179	
180	        @Override
181	        public boolean hasNext() {
182	            ensureUnmodified();
183	            return offset < size;
184	        }
185	
186	        @Override
187	        public T next() {
188	            ensureUnmodified();
189	            if (offset >= size) {
190	                throw new NoSuchElementException();
191	            }
192	
193	            T value = elementAt(indexFromHead(offset));
194	            offset++;
195	            return value;
196	        }
197	
198	        private void ensureUnmodified() {
199	            if (expectedModificationCount != modificationCount) {
200	                throw new ConcurrentModificationException();
201	            }
202	        }
203	    }
204	}
